import json
from pathlib import Path

from fallback_policy import fill_system_defaults
from mock_profile_api import TRACE as PROFILE_TRACE, get_profile
from mock_transaction_api import TRACE as TX_TRACE, send_transaction
from normalization_policy import normalize_currency
from profile_merge import merge_profile
from transaction_contract import OUTBOUND_FIELDS, REQUIRED_FIELDS


def validate_record(record):
    if not isinstance(record, dict):
        return ["record"]
    missing = [
        field_name
        for field_name in REQUIRED_FIELDS
        if field_name not in record or record[field_name] is None
    ]
    if "amount" not in missing and (
        isinstance(record["amount"], bool)
        or not isinstance(record["amount"], (int, float))
    ):
        missing.append("amount: number")
    return missing


def enrich(record):
    try:
        profile = get_profile(record["user_id"])
    except KeyError:
        # A missing profile is an expected condition; the fallback policy
        # supplies any still-incomplete fields.
        profile = {}
    merged = merge_profile(record, profile)
    return fill_system_defaults(merged)


def normalize(record):
    return normalize_currency(record)


def process_transactions(path):
    PROFILE_TRACE.clear()
    TX_TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    results = []
    failures = []
    accepted = []

    # Complete local screening before touching either external boundary.
    for index, record in enumerate(payload):
        missing = validate_record(record)
        if missing:
            failures.append({"index": index, "errors": missing})
        else:
            accepted.append((index, record))

    for index, record in accepted:
        try:
            enriched = enrich(record)
            normalized = normalize(enriched)
            missing_outbound = [
                field_name
                for field_name in OUTBOUND_FIELDS
                if normalized.get(field_name) is None
            ]
            if missing_outbound:
                failures.append({"index": index, "errors": missing_outbound})
                continue
            outbound = {field_name: normalized[field_name] for field_name in OUTBOUND_FIELDS}
            results.append(send_transaction(outbound))
        except (TypeError, ValueError) as exc:
            failures.append({"index": index, "errors": [str(exc)]})

    failures.sort(key=lambda failure: failure["index"])
    return {
        "results": results,
        "failures": failures,
        "profile_trace": list(PROFILE_TRACE),
        "tx_trace": list(TX_TRACE),
        "total": len(payload),
        "succeeded": len(results),
        "failed": len(failures),
    }
